mapper.select:
SELECT et.id, et.`name`, et.theme_id, et.theme_name, et.exam_start_time, et.exam_end_time, et.exam_paper_id, et.exam_paper_name, et.charge_user_id, et.charge_user_name, et.timed, et.exam_duration, et.exam_duration_unit, et.retake, et.retake_number, et.exam_task_type, et.exam_user_number, et.exam_task_status, et.remark FROM headquarters_exam_task et LEFT JOIN theme t on et.theme_id = t.id
et.deleted = 0
and (et.name like concat('%',#{query.keyword},'%') or t.name like concat('%',#{query.keyword},'%') or et.theme_name like concat('%',#{query.keyword},'%') )
and et.exam_task_type = #{query.examTaskType}
and et.exam_task_status = #{query.examTaskStatus}
and et.theme_id = #{query.themeId}
and et.exam_start_time >= #{query.period.begin}
and et.exam_start_time <= #{query.period.end}
order by et.exam_start_time desc

SELECT t1.id, t1.user_name, t1.user_department_name, t1.user_post_name, t2.market_tenant, t5.market_name, t3.exam_time as user_exam_begin_time, t3.exam_submitted_time as user_exam_end_time, t3.exam_duration, t1.score, t1.exam_status, t1.passed, t2.`name` as task_name, t2.theme_name, t2.charge_user_name, t2.exam_start_time, t2.exam_end_time, t2.source_key, t4.exam_paper_score as total_score, t4.exam_paper_passing_grade_score FROM exam_task_user t1 LEFT JOIN exam_task t2 on t1.exam_task_id = t2.id LEFT JOIN exam_task_user_record t3 on t1.user_exam_task_record_id = t3.id LEFT JOIN exam_task_paper t4 on t1.exam_task_id = t4.exam_task_id and t3.exam_paper_id = t4.exam_paper_id LEFT JOIN headquarters_exam_task_market t5 on t2.source_key = t5.headquarters_exam_task_id AND t2.market_tenant = t5.market_tenant_code
t1.tenant = #{tenant}
and t1.user_name like concat('%',#{query.keyword},'%')
and t1.exam_task_id = #{query.examTaskId}
and t2.theme_id = #{query.themeId}
and t2.exam_task_type = #{query.examTaskType}
and t1.exam_status = #{query.examStatus}
and t2.market_tenant = #{query.marketTenant}
and t2.exam_start_time >= #{query.period.begin}
and t2.exam_start_time <= #{query.period.end}
and t1.passed = #{query.passed}
GROUP BY t1.id order by t1.create_time desc

SELECT t1.id, t1.user_name as `name`, t1.user_department_name as department_name, t1.user_post_name as post_name, t2.market_tenant, t5.market_name, t3.exam_time AS user_exam_start_time, t3.exam_submitted_time AS user_exam_end_time, t3.exam_duration as duration, t1.score, t1.exam_status as `status`, t1.passed, t2.`name` AS task_name, t2.theme_name, t2.charge_user_name, t2.exam_start_time, t2.exam_end_time, t2.source_key, t4.exam_paper_score AS paper_score, t4.exam_paper_passing_grade_score as paper_grade_score FROM exam_task_user t1 LEFT JOIN exam_task t2 ON t1.exam_task_id = t2.id LEFT JOIN exam_task_user_record t3 ON t1.user_exam_task_record_id = t3.id LEFT JOIN exam_task_paper t4 ON t1.exam_task_id = t4.exam_task_id and t3.exam_paper_id = t4.exam_paper_id LEFT JOIN headquarters_exam_task_market t5 on t2.source_key = t5.headquarters_exam_task_id AND t2.market_tenant = t5.market_tenant_code
t1.tenant = #{tenant}
and t1.user_name like concat('%',#{query.keyword},'%')
and t1.exam_task_id = #{query.examTaskId}
and t2.theme_id = #{query.themeId}
and t2.exam_task_type = #{query.examTaskType}
and t1.exam_status = #{query.examStatus}
and t2.market_tenant = #{query.marketTenant}
and t2.exam_start_time >= #{query.period.begin}
and t2.exam_start_time <= #{query.period.end}
and t1.passed = #{query.passed}
GROUP BY t1.id order by t1.create_time desc
